document.addEventListener('submit',guarded(async ev=>{let f=ev.target;if(!f.matches('form'))return;ev.preventDefault();if(f.classList.contains('receive-form')){let fd=getForm(f);await commit(d=>receive(d,{saleId:f.dataset.sale,installmentId:f.dataset.installment,amountCents:money(fd.amount),method:fd.method}),'Pagamento parcial/total baixado na parcela escolhida.');return;}let func=submissions[f.id];if(func)await func(f);}));
document.addEventListener('change',ev=>{if(ev.target.id==='tripSelector'){currentTrip=ev.target.value;render();}});
function showLogin(hasAccount){data=null;document.documentElement.classList.remove('theme-dark');$('#app').innerHTML=`<div class="loginBg"><div class="loginPanel"><div class="brand" style="color:#174c50;padding:0 0 16px"><div class="brandmark">E</div><div>EMAVE <small>GESTÃO SEGURA</small></div></div><div class="kicker">${hasAccount?'Cofre protegido':'Primeiro acesso'}</div><h1>${hasAccount?'Bem-vindo de volta':'Crie sua senha'}</h1><p>${hasAccount?'Seus dados estão criptografados neste aparelho. Entre com a senha para acessá-los.':'Seus registros serão guardados localmente em um cofre criptografado. Guarde sua senha: não existe recuperação automática.'}</p><form id="login-form">${field('Senha','loginPassword',input('loginPassword','','password','minlength="10" required autocomplete="current-password"'))}${!hasAccount?field('Confirme a senha','loginConfirm',input('loginConfirm','','password','minlength="10" required autocomplete="new-password"')):''}<button type="submit" class="btn">${hasAccount?'Desbloquear EMAVE':'Criar cofre seguro'}</button></form><p class="mini">Funciona sem internet. Para manter cópias externas configure o backup depois de entrar.</p></div></div>`;}
async function startup(){try{showLogin(await exists());}catch(e){err(e);$('#app').textContent='Não foi possível inicializar o armazenamento seguro neste aparelho.';}}
const oldHandler=submissions['login-form'];
submissions['login-form']=async f=>{let v=getForm(f);if(await exists()){data=await login(v.loginPassword);}else{if(v.loginPassword!==v.loginConfirm)throw Error('As senhas não coincidem.');data=initialData();await initialize(v.loginPassword,data);}screen='dashboard';render();scheduleDueNotifications(data).catch(console.warn);let last=JSON.parse(localStorage.getItem('emave_last_backup')||'null');if(data.settings.backupUrl&&data.settings.backupToken&&navigator.onLine&&(!last||last.revision<data.revision))pushBackup(data.settings).then(updateBackupLabel).catch(console.warn);};
window.addEventListener('online',()=>{if(data?.settings.backupUrl&&data.settings.backupToken)pushBackup(data.settings).then(updateBackupLabel).catch(console.warn);if(data)render();});
window.addEventListener('offline',()=>{if(data)render();});
