function reportsPage(){let k=dashboard(data),saleRows=[...data.sales].reverse().slice(0,20);return `<div class="sectionHead"><div><h2>Relatórios e auditoria</h2><p>As vendas, pagamentos e baixas ficam em históricos separados para evitar dupla contabilização.</p></div><div class="toolbar">${btn('pdf-report','Relatório em PDF','secondary')}${btn('csv-sales','Exportar vendas','light')}${btn('csv-payments','Exportar pagamentos','light')}${btn('csv-expenses','Exportar despesas','light')}</div></div><div class="grid metrics">${pair(brl(k.soldMonth),'Faturamento do mês')}${pair(brl(k.receivedMonth),'Recebido no mês','Não confundir com venda')}${pair(brl(k.expenseMonth),'Despesas pagas')}${pair((k.profitMonth===null?'Custo pendente':brl(k.profitMonth)),'Lucro bruto estimado','Não representa lucro líquido')}</div><section class="card" style="margin-top:18px"><h3>Últimas vendas</h3><div class="tableWrap"><table><thead><tr><th>Venda</th><th>Cliente</th><th>Data</th><th>Recebido</th><th>A receber</th><th class="rightAlign">Total</th></tr></thead><tbody>${saleRows.map(s=>`<tr><td>${s.initialBalance?'Saldo inicial':'#'+s.number}</td><td>${esc(nam(s.clientId,data.customers,'À vista'))}</td><td>${fmtDate(s.date)}</td><td>${brl(paidSale(s))}</td><td>${brl(amountSale(s)-paidSale(s))}</td><td class="rightAlign"><b>${brl(amountSale(s))}</b></td></tr>`).join('')}</tbody></table></div>${!saleRows.length?empty('Sem vendas lançadas.'):''}</section><section class="card" style="margin-top:18px"><h3>Últimas ações registradas</h3>${data.audit.length?data.audit.slice(-15).reverse().map(a=>`<div class="cartRow"><div><b>${esc(a.action)}</b><div class="hint">${esc(a.detail)}</div></div><div class="mini muted">${new Date(a.at).toLocaleString('pt-BR')}</div></div>`).join(''):empty('Nenhuma ação no histórico.')}</section>`;}
function catalogText(){let prod=[...data.products].filter(p=>p.qty>0&&!p.restricted&&!/jefferson/i.test(p.location||'')).sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name));let groups=new Map();for(let p of prod){if(!groups.has(p.category))groups.set(p.category,[]);groups.get(p.category).push(`${p.name} — ${brl(p.priceCents)}`);}return [`🛍️ *${data.settings.company.toUpperCase()}*`,'✨ Produtos disponíveis ✨',...Array.from(groups,([cat,lines])=>`\n*${cat.toUpperCase()}*\n\n${lines.join('\n\n')}`),'\n📲 WhatsApp: '+data.settings.phone,'📸 Instagram: '+data.settings.instagram,'📦 Consulte disponibilidade e entrega.'].join('\n');}
function catalogPage(){let content=catalogText();return `<div class="sectionHead"><div><h2>Lista para WhatsApp</h2><p>Um produto por linha, com espaço; inclui apenas estoque positivo e itens sem restrição de publicidade.</p></div>${btn('copy-catalog','Copiar lista para WhatsApp','')}</div><section class="card"><pre style="white-space:pre-wrap;word-break:break-word;line-height:1.9;font:14px 'DM Sans',sans-serif">${esc(content)}</pre>${!data.products.some(p=>p.qty>0&&!p.restricted&&!/jefferson/i.test(p.location||''))?'<div class="notice">Ainda não há produtos com estoque confirmado. Importe o catálogo e registre as quantidades antes de divulgar.</div>':''}</section>`;}
function settingsPage(){let status=JSON.parse(localStorage.getItem('emave_last_backup')||'null');return `<div class="sectionHead"><div><h2>Configurações e backup</h2><p>O cofre local usa AES-GCM com chave derivada da senha. Você precisa lembrar a senha para restaurar backups.</p></div></div><div class="grid cards2"><section class="card"><h3>Dados da empresa e cópias remotas</h3><form id="settings-form"><div class="form-grid two">${field('Empresa','company',input('company',data.settings.company,'text','required'))}${field('WhatsApp','phone',input('phone',data.settings.phone,'tel'))}${field('Instagram','instagram',input('instagram',data.settings.instagram,'text'))}${field('E-mail para receber backup','backupEmail',input('backupEmail',data.settings.backupEmail,'email','placeholder="seuemail@exemplo.com"'))}${field('URL HTTPS do backend','backupUrl',input('backupUrl',data.settings.backupUrl,'url','placeholder="https://seudominio.com/api"'))}${field('Token secreto do servidor','backupToken',input('backupToken',data.settings.backupToken,'password','autocomplete="off"'))}</div><div style="margin-top:14px" class="field"><label><input type="checkbox" style="width:auto" name="notifications" ${data.settings.notifications?'checked':''}/> Alertas Android de vencimento (pode precisar de permissão)</label><label><input type="checkbox" style="width:auto" name="dark" ${data.settings.dark?'checked':''}/> Modo escuro</label></div><div class="actions"><button type="submit" class="btn">Salvar ajustes</button></div></form><hr/><div class="hint">Último envio confirmado: ${status?new Date(status.at).toLocaleString('pt-BR')+' • revisão '+status.revision:'nunca'}.</div><div class="actions">${btn('backup-email','Enviar backup para o Gmail','')}${btn('backup-now','Sincronizar cópia com servidor','secondary')}${btn('backup-download','Salvar backup criptografado','light')}</div></section>
 <section class="card"><h3>Recuperação e importação</h3><p class="hint">Restauração substituirá os dados locais. Antes, baixe uma cópia de segurança.</p>${field('Arquivo de backup .json','restoreInput','<input type="file" id="restoreInput" accept="application/json,.json"/>')}<div class="actions">${btn('restore-file','Restaurar arquivo (substitui dados)','danger')}</div><hr/><h3>Catálogo inicial EMAVE</h3><p class="hint">Preços de referência históricos, sem adicionar dívidas, vendas ou estoque fictício.</p><div class="actions">${btn('seed-catalog','Carregar catálogo EMAVE (sem estoque)','secondary')}</div><hr/><h3>Importar produtos via CSV</h3><p class="hint">Colunas: nome;categoria;preco;custo;restrito. Somente novos produtos, com estoque zero.</p><input id="csvInput" type="file" accept=".csv,text/csv"/><div class="actions">${btn('import-products','Importar produtos CSV','light')}</div></section>
 <section class="card"><h3>Segurança</h3><form id="change-password-form"><div class="form-grid two">${field('Nova senha do cofre','newPassword',input('newPassword','','password','required minlength="10"'))}${field('Confirme a nova senha','confirmPassword',input('confirmPassword','','password','required minlength="10"'))}</div><div class="actions"><button class="btn secondary" type="submit">Alterar senha do cofre</button></div></form><p class="hint">A senha não é enviada ao servidor. Perdê-la impede abrir backups anteriores criptografados com ela.</p></section><section class="card"><h3>Informações importantes</h3><p class="hint"><b>Enviar para Gmail:</b> abre o compartilhamento Android com o arquivo criptografado anexado; escolha o aplicativo, confira o destinatário e toque Enviar. O envio não ocorre sem sua confirmação.</p><p class="hint"><b>Backup automático por e-mail:</b> requer servidor HTTPS + token e cron na hospedagem. Enquanto o app está aberto e online, sincroniza alterações; o cron pode enviar a última cópia sincronizada, mas não acessa dados ainda offline ou com o app fechado.</p><p class="hint"><b>Vários aparelhos:</b> esta edição opera em um aparelho principal. O backend armazena cópias criptografadas, não faz sincronização simultânea de vendas de múltiplos celulares.</p><p class="hint"><b>Histórico Excel:</b> não é importado automaticamente. Faça conferência e migração assistida antes de iniciar operações reais.</p></section></div>`;}
import {starterProducts} from './starter.js';
function csvExport(kind){let rows=[];if(kind==='products')rows=[['Código','Produto','Categoria','Qtd.','Preço R$','Custo R$'],...data.products.map(p=>[p.id,p.name,p.category,p.qty,dec(p.priceCents),dec(p.costCents)])];if(kind==='debts')rows=[['Venda','Cliente','Parcela','Vencimento','Saldo R$'],...openInstallments(data).map(i=>[i.saleNumber,nam(i.clientId,data.customers),i.n,i.due,dec(i.remainingCents)])];if(kind==='sales')rows=[['Venda','Data','Cliente','Total R$','Recebido R$','A receber R$','Custo R$'],...data.sales.map(s=>[s.number,s.date,nam(s.clientId,data.customers,'À vista'),dec(amountSale(s)),dec(paidSale(s)),dec(amountSale(s)-paidSale(s)),dec(s.items.reduce((a,i)=>a+i.costTotalCents,0))])];if(kind==='payments')rows=[['Data','Venda ID','Cliente','Forma','Valor R$'],...data.payments.map(p=>[p.date,p.saleId,nam(p.clientId,data.customers),p.method,dec(p.amountCents)])];if(kind==='expenses')rows=[['Data','Descrição','Categoria','Viagem','Rateio','Pagamento','Valor R$'],...data.expenses.map(e=>[e.date,e.description,e.category,e.tripId?data.trips.find(t=>t.id===e.tripId)?.name:'',e.rateable?'Sim':'Não',e.method,dec(e.amountCents)])];downloadBlob(toCsv(rows),`EMAVE-${kind}-${today()}.csv`,'text/csv;charset=utf-8');}
function parseCsv(text){let delimiter=text.split(/\r?\n/)[0].includes(';')?';':',';let rows=[],row=[],s='',quoted=false;for(let i=0;i<text.length;i++){let ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){s+='"';i++;}else quoted=!quoted;}else if(ch===delimiter&&!quoted){row.push(s);s='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(s);if(row.some(x=>x.trim()))rows.push(row);row=[];s='';}else{s+=ch;}}row.push(s);if(row.some(x=>x.trim()))rows.push(row);return rows;}
async function exportPdfReport(){const k=dashboard(data),ins=openInstallments(data);let lines=[`Data: ${fmtDate(today())}`,`Vendas do mes: ${brl(k.soldMonth)}`,`Recebido no mes: ${brl(k.receivedMonth)}`,`Contas a receber: ${brl(k.receivable)}`,`Em atraso: ${brl(k.overdue)}`,`Despesas pagas: ${brl(k.expenseMonth)}`,`Lucro bruto estimado: ${(k.profitMonth===null?'Custo pendente':brl(k.profitMonth))}`,'','CONTAS A RECEBER',...ins.map(i=>`${nam(i.clientId,data.customers)} | ${fmtDate(i.due)} | Venda ${i.saleNumber} | ${brl(i.remainingCents)}`),'','ULTIMAS VENDAS',...data.sales.slice(-40).reverse().map(s=>`${fmtDate(s.date)} | ${nam(s.clientId,data.customers,'A vista')} | ${brl(amountSale(s))} | Recebido ${brl(paidSale(s))}`)];return downloadBlob(makePdf({title:'EMAVE IMPORTADOS - RELATORIO FINANCEIRO',lines,footer:'Relatorio de uso interno - confirmar custos pendentes'}),`EMAVE-relatorio-${today()}.pdf`,'application/pdf');}
function wpp(c){let amount=clientBalance(data,c.id);if(!c.phone)throw Error('Cliente sem WhatsApp.');let phone=c.phone.startsWith('55')?c.phone:'55'+c.phone;let text=`Olá, ${c.name}! Aqui é da EMAVE Importados. Consta um saldo de ${brl(amount)} em aberto. Podemos combinar o pagamento? Obrigado!`;window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(text),'_blank','noopener');}
const clickActions={
 'go-pos':()=>{screen='pos';render();},'go-receivables':()=>{screen='receivables';render();},'go-products':()=>{screen='products';render();},'go-catalog':()=>{screen='catalog';render();},
 'logout':()=>{logout();data=null;cart=[];showLogin(false);},
 'remove-cart':(el)=>{cart.splice(Number(el.dataset.index),1);render();},
 'whatsapp':(el)=>{wpp(data.customers.find(c=>c.id===el.dataset.id));},
 'price-edit':async el=>{let p=data.products.find(p=>p.id===el.dataset.id);let v=prompt(`Novo preço de ${p.name} (R$)`,dec(p.priceCents));if(v===null)return;let price=money(v);if(price<0)throw Error('Preço não pode ser negativo.');await commit(d=>{let x=d.products.find(x=>x.id===p.id);let before=x.priceCents;x.priceCents=price;d.audit.push({at:new Date().toISOString(),action:'alteracao_preco',detail:`${p.name}: ${brl(before)} → ${brl(price)}`});},'Preço alterado sem modificar vendas antigas.');},
 'copy-catalog':async()=>{await navigator.clipboard.writeText(catalogText());msg('Lista copiada. Cole no WhatsApp.');},
 'seed-trip':async()=>{if(!confirm('Importar somente as duas despesas confirmadas de 20/11 (pedágio R$ 11,70 e combustível R$ 30,00)? Não altera o estoque.'))return;await commit(d=>seedTripNov20(d),'Viagem 20/11 importada: R$ 41,70, sem movimentar estoque.');screen='trips';render();},
 'close-trip':async(el)=>{let id=el.dataset.id;if(!confirm('ATENÇÃO: após conferir a lista, encerrar viagem e efetivar TODAS as entradas de estoque com rateio proporcional ao valor das compras?'))return;await commit(d=>closeTrip(d,id,'value'),'Viagem encerrada: mercadorias entraram no estoque com o custo rateado.');},
 'pdf-report':()=>exportPdfReport(),
 'csv-products':()=>csvExport('products'),'csv-debts':()=>csvExport('debts'),'csv-sales':()=>csvExport('sales'),'csv-payments':()=>csvExport('payments'),'csv-expenses':()=>csvExport('expenses'),
 'backup-now':async()=>{await pushBackup(data.settings);msg('Backup criptografado recebido pelo servidor. O envio por email depende do cron configurado.');updateBackupLabel();},'backup-email':async()=>{msg('Escolha Gmail ou outro aplicativo de e-mail, confira o destinatário e confirme Enviar.');const result=await emailBackup(data.settings.backupEmail);if(!result.shared)msg('Backup baixado. Para enviar por e-mail, anexe o arquivo no Gmail.');},'backup-download':downloadBackup,
 'restore-file':async()=>{const file=$('#restoreInput')?.files[0];if(!file)throw Error('Selecione um arquivo .json.');if(!confirm('Isso irá SUBSTITUIR TODO o cofre local. Faça antes um backup do estado atual. Continuar?'))return;let pw=prompt('Digite a SENHA utilizada quando o arquivo foi gerado:');if(!pw)return;const content=JSON.parse(await file.text());data=await restoreEncrypted(content,pw);cart=[];screen='dashboard';render();msg('Backup restaurado.');},
 'seed-catalog':async()=>{if(!confirm(`Importar ${starterProducts.length} produtos de referência com estoque ZERO? Produtos já existentes não serão duplicados.`))return;let n=0;await commit(d=>{for(const [name,category,price,cost=0,restricted=false] of starterProducts){if(!d.products.some(x=>x.name.toLowerCase()===name.toLowerCase())){addProduct(d,{name,category,priceCents:money(price),costCents:money(cost),restricted});n++;}}},'Catálogo de referência carregado. Quantidades permanecem zero.');msg(`${n} novos produtos cadastrados.`);},
 'import-products':async()=>{let file=$('#csvInput')?.files[0];if(!file)throw Error('Selecione um arquivo CSV.');let rows=parseCsv((await file.text()).replace(/^\ufeff/,''));if(rows.length<2)throw Error('CSV vazio.');let header=rows.shift().map(x=>x.toLowerCase().trim());let idx=name=>header.indexOf(name);if(idx('nome')<0||idx('preco')<0)throw Error('CSV precisa das colunas nome e preco.');if(!confirm(`Importar até ${rows.length} produtos novos com quantidade zero?`))return;let count=0;await commit(d=>{for(let row of rows){let name=row[idx('nome')]?.trim();if(!name||d.products.some(p=>p.name.toLowerCase()===name.toLowerCase()))continue;addProduct(d,{name,category:row[idx('categoria')]||'Outros',priceCents:money(row[idx('preco')]),costCents:money(row[idx('custo')]||'0'),restricted:/^(sim|true|1)$/i.test(row[idx('restrito')]||'')});count++;}},`${count} produtos importados, sem alterar estoque.`);},
};
document.addEventListener('click',guarded(async ev=>{let nav=ev.target.closest('[data-nav]');if(nav){screen=nav.dataset.nav;render();return;}let action=ev.target.closest('[data-action]');if(action){let func=clickActions[action.dataset.action];if(func)await func(action);}}));
const submissions={
 'cart-add':async f=>{let v=getForm(f);let p=data.products.find(p=>p.id===v.cartProduct);if(!p)throw Error('Escolha um produto disponível.');let q=Number(v.cartQty);if(q<=0||!Number.isFinite(q))throw Error('Quantidade inválida.');let existing=cart.filter(x=>x.productId===p.id).reduce((a,i)=>a+i.qty,0);if(q+existing>p.qty)throw Error(`Estoque de ${p.name} insuficiente.`);let price=v.cartPrice.trim()?money(v.cartPrice):p.priceCents;if(price<0)throw Error('Preço inválido.');cart.push({productId:p.id,qty:q,priceCents:price});render();},
 'sale-form':async f=>{if(!cart.length)throw Error('Adicione produtos ao carrinho.');let v=getForm(f),mode=v.saleMode;let count=Number(v.saleCount);if(mode==='paid')count=1;await commit(d=>createSale(d,{clientId:v.saleClient,items:cart,date:today(),method:v.saleMethod,mode,installmentCount:count,firstDue:v.saleDue,initialPaidCents:money(v.salePaid),customInstallmentsCents:v.saleCustom?.trim()?v.saleCustom.split(';').map(x=>money(x)):null}),'Venda registrada e estoque baixado.');cart=[];screen='dashboard';render();},
 'product-form':async f=>{let v=getForm(f);await commit(d=>addProduct(d,{name:v.prodName,category:v.prodCat,priceCents:money(v.prodPrice),costCents:money(v.prodCost),restricted:Boolean(v.prodRestricted)}),'Produto cadastrado. Estoque inicial zero.');},
 'stock-form':async f=>{let v=getForm(f);await commit(d=>addStock(d,{productId:v.stockProduct,qty:Number(v.stockQty),unitCostCents:money(v.stockCost),date:v.stockDate}),'Entrada gravada com lote de custo.');},
 'client-form':async f=>{let v=getForm(f);await commit(d=>addCustomer(d,{name:v.clientName,phone:v.clientPhone,note:v.clientNote}),'Cliente cadastrado.');},
 'opening-form':async f=>{let v=getForm(f);if(!confirm('Confirma que este saldo anterior está validado e ainda NÃO foi lançado?'))return;await commit(d=>registerOpeningBalance(d,{clientId:v.openClient,amountCents:money(v.openAmount),due:v.openDue}),'Saldo anterior registrado sem gerar nova venda ou movimentar estoque.');},
 'trip-form':async f=>{let v=getForm(f);let id;await commit(d=>{id=newTrip(d,{name:v.tripName,date:v.tripDate}).id;},'Viagem aberta; estoque permanece intacto.');currentTrip=id;screen='trips';render();},
 'trip-expense-form':async f=>{let v=getForm(f);await commit(d=>addExpense(d,{description:v.travelDesc,amountCents:money(v.travelValue),date:v.travelDate,category:v.travelCat,tripId:currentTrip,rateable:Boolean(v.travelRateable),method:v.travelMethod}),'Despesa registrada na viagem.');},
 'trip-item-form':async f=>{let v=getForm(f);await commit(d=>addTripItem(d,{tripId:currentTrip,productId:v.tripProduct,qty:Number(v.tripQty),unitCostForeignCents:money(v.tripUnitCost),currency:v.tripCurrency,fxToBRL:Number(v.tripFx),vendor:v.tripVendor}),'Produto reservado no registro da viagem; ainda NÃO entrou no estoque.');},
 'expense-form':async f=>{let v=getForm(f);await commit(d=>addExpense(d,{description:v.expDesc,amountCents:money(v.expValue),date:v.expDate,category:v.expCat,method:v.expMethod}),'Despesa geral registrada.');},
 'settings-form':async f=>{let v=getForm(f);let url=v.backupUrl.trim();if(url&&!/^https:\/\//i.test(url))throw Error('Servidor de backup deve usar HTTPS.');await commit(d=>Object.assign(d.settings,{company:v.company,phone:v.phone,instagram:v.instagram,backupEmail:v.backupEmail,backupUrl:url,backupToken:v.backupToken,notifications:Boolean(v.notifications),dark:Boolean(v.dark)}),'Configurações salvas.');},
 'change-password-form':async f=>{let v=getForm(f);if(v.newPassword!==v.confirmPassword)throw Error('As senhas novas não coincidem.');if(!confirm('Alterar senha criptografa os dados com chave nova. BACKUPS ANTIGOS precisarão da senha anterior para abrir. Continuar?'))return;const revisionData=structuredClone(data);revisionData.revision++;revisionData.updatedAt=new Date().toISOString();await changePassword(revisionData,v.newPassword);data=revisionData;render();msg('Senha alterada. Salve um backup novo.');},
};
document.addEventListener('submit',guarded(async ev=>{let f=ev.target;if(!f.matches('form'))return;ev.preventDefault();if(f.classList.contains('receive-form')){let fd=getForm(f);await commit(d=>receive(d,{saleId:f.dataset.sale,installmentId:f.dataset.installment,amountCents:money(fd.amount),method:fd.method}),'Pagamento parcial/total baixado na parcela escolhida.');return;}let func=submissions[f.id];if(func)await func(f);}));
document.addEventListener('change',ev=>{if(ev.target.id==='tripSelector'){currentTrip=ev.target.value;render();}});
function showLogin(hasAccount){data=null;document.documentElement.classList.remove('theme-dark');$('#app').innerHTML=`<div class="loginBg"><div class="loginPanel"><div class="brand" style="color:#174c50;padding:0 0 16px"><div class="brandmark">E</div><div>EMAVE <small>GESTÃO SEGURA</small></div></div><div class="kicker">${hasAccount?'Cofre protegido':'Primeiro acesso'}</div><h1>${hasAccount?'Bem-vindo de volta':'Crie sua senha'}</h1><p>${hasAccount?'Seus dados estão criptografados neste aparelho. Entre com a senha para acessá-los.':'Seus registros serão guardados localmente em um cofre criptografado. Guarde sua senha: não existe recuperação automática.'}</p><form id="login-form">${field('Senha','loginPassword',input('loginPassword','','password','minlength="10" required autocomplete="current-password"'))}${!hasAccount?field('Confirme a senha','loginConfirm',input('loginConfirm','','password','minlength="10" required autocomplete="new-password"')):''}<button type="submit" class="btn">${hasAccount?'Desbloquear EMAVE':'Criar cofre seguro'}</button></form><p class="mini">Funciona sem internet. Para manter cópias externas configure o backup depois de entrar.</p></div></div>`;}
async function startup(){try{showLogin(await exists());}catch(e){err(e);$('#app').textContent='Não foi possível inicializar o armazenamento seguro neste aparelho.';}}
const oldHandler=submissions['login-form'];
submissions['login-form']=async f=>{let v=getForm(f);if(await exists()){data=await login(v.loginPassword);}else{if(v.loginPassword!==v.loginConfirm)throw Error('As senhas não coincidem.');data=initialData();await initialize(v.loginPassword,data);}screen='dashboard';render();scheduleDueNotifications(data).catch(console.warn);let last=JSON.parse(localStorage.getItem('emave_last_backup')||'null');if(data.settings.backupUrl&&data.settings.backupToken&&navigator.onLine&&(!last||last.revision<data.revision))pushBackup(data.settings).then(updateBackupLabel).catch(console.warn);};
window.addEventListener('online',()=>{if(data?.settings.backupUrl&&data.settings.backupToken)pushBackup(data.settings).then(updateBackupLabel).catch(console.warn);if(data)render();});
window.addEventListener('offline',()=>{if(data)render();});
startup();

// Ao voltar ao app depois de alguns minutos, exige a senha novamente.
let wentHiddenAt=0;
document.addEventListener('visibilitychange',async()=>{if(document.hidden){wentHiddenAt=Date.now();return;}if(data&&wentHiddenAt&&Date.now()-wentHiddenAt>5*60*1000){logout();data=null;cart=[];showLogin(true);msg('Sessão bloqueada por inatividade.');}wentHiddenAt=0;});
